typedef struct TrieNode {
  struct TrieNode *child[26];
  int is_end;
} TrieNode;

TrieNode *node_new(void) { return calloc(1, sizeof(TrieNode)); }

void insert(TrieNode *root, const char *w) {
  for (; *w; w++) {
    int c = *w - 'a';
    if (!root->child[c]) root->child[c] = node_new();
    root = root->child[c];
  }
  root->is_end = 1;
}
int search(TrieNode *root, const char *w) {
  for (; *w; w++) { root = root->child[*w - 'a']; if (!root) return 0; }
  return root->is_end;
}
